'use client';

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/Button';
import { BookLoader } from '@/components/ui/BookLoader';
import { SkeletonLine } from '@/components/ui/Skeleton';
import { Toast } from '@/components/ui/Toast';
import type { FormQuestion, QuestionType } from '@/types/form-question';

type DraftSection = { id: string; title: string; description: string; display_order: number; active: boolean };
type DraftQuestion = FormQuestion & { section_id: string | null };
type SectionForm = { title: string; description: string; active: boolean };
const emptySection: SectionForm = { title: '', description: '', active: true };
const emptyQuestion = (sectionId: string, displayOrder: number): Omit<DraftQuestion, 'id'> => ({ field_key: '', label: '', type: 'text', number_format: 'integer', required: false, allow_alphabets: true, allow_numbers: true, allow_special_characters: true, max_length: 255, options: [], display_order: displayOrder, section_id: sectionId, active: true, placeholder: '' });
const cloneQuestions = (questions: DraftQuestion[]) => questions.map(question => ({ ...question, options: [...question.options] }));
const newId = () => crypto.randomUUID();

export function QuestionsManager() {
  const [saved, setSaved] = useState<{ sections: DraftSection[]; questions: DraftQuestion[] }>({ sections: [], questions: [] });
  const [draft, setDraft] = useState(saved);
  const [editingSection, setEditingSection] = useState<string | null>(null);
  const [sectionForm, setSectionForm] = useState<SectionForm>(emptySection);
  const [editingQuestion, setEditingQuestion] = useState<string | null>(null);
  const [questionForm, setQuestionForm] = useState<Omit<DraftQuestion, 'id'>>(emptyQuestion('', 0));
  const [optionsText, setOptionsText] = useState('');
  const [dragged, setDragged] = useState<{ type: 'section' | 'question'; id: string } | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ type: 'section' | 'question'; id: string } | null>(null);
  const [deleteText, setDeleteText] = useState('');
  const [notice, setNotice] = useState<{ text: string; error?: boolean } | null>(null);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);

  async function load() { try { const response = await fetch('/api/admin/form-questions', { cache: 'no-store' }); if (!response.ok) { setNotice({ text: 'Unable to load form configuration.', error: true }); return; } const data = await response.json(); const next = { sections: data.sections ?? [], questions: cloneQuestions(data.questions ?? []) }; setSaved(next); setDraft(next); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const hasChanges = JSON.stringify(saved) !== JSON.stringify(draft);
  const questionsIn = (sectionId: string) => draft.questions.filter(question => question.section_id === sectionId).sort((a, b) => a.display_order - b.display_order);
  function openSection(section?: DraftSection) { setEditingSection(section?.id ?? newId()); setSectionForm(section ? { title: section.title, description: section.description, active: section.active } : emptySection); }
  function applySection(event: React.FormEvent) { event.preventDefault(); if (!editingSection || !sectionForm.title.trim()) return; setDraft(previous => { const exists = previous.sections.some(section => section.id === editingSection); const section = { id: editingSection, ...sectionForm, title: sectionForm.title.trim(), display_order: exists ? previous.sections.find(item => item.id === editingSection)!.display_order : (previous.sections.length + 1) * 10 }; return { ...previous, sections: exists ? previous.sections.map(item => item.id === editingSection ? section : item) : [...previous.sections, section] }; }); setEditingSection(null); }
  function openQuestion(question?: DraftQuestion, sectionId?: string) { const targetSection = sectionId ?? question?.section_id ?? draft.sections[0]?.id ?? ''; setEditingQuestion(question?.id ?? newId()); setQuestionForm(question ? { ...question, options: [...question.options] } : emptyQuestion(targetSection, questionsIn(targetSection).length * 10 + 10)); setOptionsText(question?.options.join('\n') ?? ''); }
  function applyQuestion(event: React.FormEvent) { event.preventDefault(); if (!editingQuestion || !questionForm.field_key || !questionForm.label) return; const question = { ...questionForm, id: editingQuestion, options: questionForm.type === 'select' ? optionsText.split('\n').map(value => value.trim()).filter(Boolean) : [] } as DraftQuestion; setDraft(previous => ({ ...previous, questions: previous.questions.some(item => item.id === editingQuestion) ? previous.questions.map(item => item.id === editingQuestion ? question : item) : [...previous.questions, question] })); setEditingQuestion(null); }
  function updateQuestion(name: string, value: unknown) { setQuestionForm(previous => ({ ...previous, [name]: value })); }
  function requestDelete(type: 'section' | 'question', id: string) { setDeleteTarget({ type, id }); setDeleteText(''); }
  function confirmDelete() { if (!deleteTarget || deleteText !== 'DELETE') return; if (deleteTarget.type === 'section' && questionsIn(deleteTarget.id).length) { setNotice({ text: 'Move all questions out of this section before deleting it.', error: true }); setDeleteTarget(null); return; } setDraft(previous => deleteTarget.type === 'section' ? { sections: previous.sections.filter(section => section.id !== deleteTarget.id), questions: previous.questions } : { sections: previous.sections, questions: previous.questions.filter(question => question.id !== deleteTarget.id) }); setDeleteTarget(null); }
  function reorderSections(targetId: string) { if (!dragged || dragged.type !== 'section' || dragged.id === targetId) return; setDraft(previous => { const sections = [...previous.sections]; const from = sections.findIndex(section => section.id === dragged.id); const to = sections.findIndex(section => section.id === targetId); const [item] = sections.splice(from, 1); sections.splice(to, 0, item); return { ...previous, sections: sections.map((section, index) => ({ ...section, display_order: (index + 1) * 10 })) }; }); setDragged(null); }
  function moveQuestion(targetSectionId: string | null, targetQuestionId?: string) { if (!dragged || dragged.type !== 'question' || dragged.id === targetQuestionId) return; setDraft(previous => { const moved = previous.questions.find(question => question.id === dragged.id); if (!moved) return previous; const source = previous.questions.filter(question => question.id !== moved.id); const destination = source.filter(question => question.section_id === targetSectionId); const targetIndex = targetQuestionId ? destination.findIndex(question => question.id === targetQuestionId) : destination.length; destination.splice(Math.max(targetIndex, 0), 0, { ...moved, section_id: targetSectionId }); const ordered = [...previous.sections.map(section => section.id), null].flatMap(sectionId => sectionId === targetSectionId ? destination : source.filter(question => question.section_id === sectionId)).map((question, index) => ({ ...question, display_order: (index + 1) * 10 })); return { ...previous, questions: ordered }; }); setDragged(null); }
  async function saveChanges() { if (saving) return; setSaving(true); setNotice(null); const deletedSections = saved.sections.filter(section => !draft.sections.some(item => item.id === section.id)).map(section => section.id); const deletedQuestions = saved.questions.filter(question => !draft.questions.some(item => item.id === question.id)).map(question => question.id); try { const response = await fetch('/api/admin/form-questions', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sections: draft.sections, questions: draft.questions, deletedSectionIds: deletedSections, deletedQuestionIds: deletedQuestions, deleteConfirmation: deletedSections.length || deletedQuestions.length ? 'DELETE' : undefined }) }); const result = await response.json(); if (!response.ok) { setNotice({ text: result.error ?? 'Unable to save changes.', error: true }); return; } const next = { sections: result.sections ?? [], questions: cloneQuestions(result.questions ?? []) }; setSaved(next); setDraft(next); setNotice({ text: 'Changes saved successfully.' }); } catch { setNotice({ text: 'Unable to save changes.', error: true }); } finally { setSaving(false); } }

  return <main className="container admin-shell"><header className="admin-header"><div><p className="eyebrow">Form configuration</p><h1>Questions</h1><p className="admin-subtitle">Organize sections and questions shown on the public enquiry form.</p></div><div className="admin-actions"><Button variant="secondary" onClick={() => openSection()} disabled={loading || saving}>+ Add Section</Button><Button onClick={() => openQuestion()} disabled={loading || saving}>+ Add Question</Button></div></header>
    <section className="admin-content-card questions-card"><div className="questions-toolbar"><span>{hasChanges ? 'Unsaved changes' : 'All changes saved'}</span><Button variant="secondary" disabled={!hasChanges || saving} onClick={saveChanges}>{saving ? <BookLoader inline text="Saving..." /> : 'Save Changes'}</Button></div>{notice && <Toast message={notice.text} error={notice.error} onClose={() => setNotice(null)} />}{loading && <div className="questions-loading" role="status" aria-label="Loading questions"><SkeletonLine width="35%" height={24} /><SkeletonLine width="72%" height={16} /><SkeletonLine width="92%" height={16} /><SkeletonLine width="64%" height={16} /></div>}
      <div className="form-sections-tree">{draft.sections.map(section => <section className={`form-section-editor${section.active ? '' : ' is-disabled'}`} key={section.id} draggable onDragStart={() => setDragged({ type: 'section', id: section.id })} onDragOver={event => event.preventDefault()} onDrop={() => reorderSections(section.id)}><header className="form-section-header"><div><p className="section-eyebrow">Section</p><h2>{section.title}</h2><p>{section.description || 'No description'}</p></div><div className="section-actions"><span className="status-badge">{section.active ? 'Active' : 'Disabled'}</span><button type="button" onClick={() => openSection(section)}>Edit</button><button type="button" onClick={() => requestDelete('section', section.id)}>Delete</button><button type="button" onClick={() => openQuestion(undefined, section.id)}>+ Question</button></div></header><div className="section-question-list">{questionsIn(section.id).map(question => <article className="section-question-row" key={question.id} draggable onDragStart={event => { event.stopPropagation(); setDragged({ type: 'question', id: question.id }); }} onDragOver={event => event.preventDefault()} onDrop={() => moveQuestion(section.id, question.id)}><div><strong>{question.label}</strong><small>{question.field_key} · {question.type} · {question.required ? 'Required' : 'Optional'} <span className={`question-status-badge ${question.active ? 'is-active' : 'is-inactive'}`}>{question.active ? 'ACTIVE' : 'INACTIVE'}</span></small></div><div className="question-actions"><button type="button" onClick={() => openQuestion(question)}>Edit</button><button type="button" onClick={() => requestDelete('question', question.id)}>Delete</button></div></article>)}{!questionsIn(section.id).length && <p className="empty-section" onDragOver={event => event.preventDefault()} onDrop={() => moveQuestion(section.id)}>Drop questions here or add one.</p>}</div></section>)}<section className="form-section-editor unassigned-section"><header className="form-section-header"><div><p className="section-eyebrow">Not published</p><h2>Unassigned questions</h2><p>These questions are retained but do not appear on the public form.</p></div></header><div className="section-question-list">{questionsIn('') .concat(draft.questions.filter(question => question.section_id === null).sort((a, b) => a.display_order - b.display_order)).map(question => <article className="section-question-row" key={question.id} draggable onDragStart={() => setDragged({ type: 'question', id: question.id })} onDragOver={event => event.preventDefault()} onDrop={() => moveQuestion(null, question.id)}><div><strong>{question.label}</strong><small>{question.field_key} · {question.type} · {question.required ? 'Required' : 'Optional'} <span className={`question-status-badge ${question.active ? 'is-active' : 'is-inactive'}`}>{question.active ? 'ACTIVE' : 'INACTIVE'}</span></small></div><div className="question-actions"><button type="button" onClick={() => openQuestion(question)}>Edit</button><button type="button" onClick={() => requestDelete('question', question.id)}>Delete</button></div></article>)}<p className="empty-section" onDragOver={event => event.preventDefault()} onDrop={() => moveQuestion(null)}>Drop questions here to unassign.</p></div></section></div>
    </section>
    {editingSection && <div className="modal-backdrop"><form className="question-dialog" onSubmit={applySection}><div className="section-heading"><h2>{draft.sections.some(section => section.id === editingSection) ? 'Edit section' : 'Add section'}</h2><button type="button" onClick={() => setEditingSection(null)}>Cancel</button></div><div className="question-form-grid"><label className="field-full">Title<input required value={sectionForm.title} onChange={event => setSectionForm(previous => ({ ...previous, title: event.target.value }))} /></label><label className="field-full">Description<textarea value={sectionForm.description} onChange={event => setSectionForm(previous => ({ ...previous, description: event.target.value }))} /></label><label><input type="checkbox" checked={sectionForm.active} onChange={event => setSectionForm(previous => ({ ...previous, active: event.target.checked }))} /> Active</label></div><Button type="submit">Apply to draft</Button></form></div>}
    {editingQuestion && <div className="modal-backdrop"><form className="question-dialog" onSubmit={applyQuestion}><div className="section-heading"><h2>{draft.questions.some(question => question.id === editingQuestion) ? 'Edit question' : 'Add question'}</h2><button type="button" onClick={() => setEditingQuestion(null)}>Cancel</button></div><div className="question-form-grid"><label>Field key<input required pattern="[A-Za-z][A-Za-z0-9_]*" value={questionForm.field_key} disabled={draft.questions.some(question => question.id === editingQuestion)} onChange={event => updateQuestion('field_key', event.target.value)} /></label><label>Label<input required value={questionForm.label} onChange={event => updateQuestion('label', event.target.value)} /></label><label>Section<select value={questionForm.section_id ?? ''} onChange={event => updateQuestion('section_id', event.target.value || null)}><option value="">Unassigned</option>{draft.sections.map(section => <option value={section.id} key={section.id}>{section.title}</option>)}</select></label><label>Type<select value={questionForm.type} onChange={event => updateQuestion('type', event.target.value as QuestionType)}>{['text', 'number', 'email', 'date', 'textarea', 'select', 'phone'].map(type => <option key={type}>{type}</option>)}</select></label><label>Max length<input required type="number" min="1" max="10000" value={questionForm.max_length} onChange={event => updateQuestion('max_length', Number(event.target.value))} /></label><label>Placeholder<input value={questionForm.placeholder ?? ''} onChange={event => updateQuestion('placeholder', event.target.value)} /></label>{questionForm.type === 'select' && <label className="field-full">Options, one per line<textarea value={optionsText} onChange={event => setOptionsText(event.target.value)} /></label>}<label><input type="checkbox" checked={questionForm.active} onChange={event => updateQuestion('active', event.target.checked)} /> Active</label><label><input type="checkbox" checked={questionForm.required} onChange={event => updateQuestion('required', event.target.checked)} /> Required</label><label><input type="checkbox" checked={questionForm.allow_alphabets} onChange={event => updateQuestion('allow_alphabets', event.target.checked)} /> Allow alphabets</label><label><input type="checkbox" checked={questionForm.allow_numbers} onChange={event => updateQuestion('allow_numbers', event.target.checked)} /> Allow numbers</label><label><input type="checkbox" checked={questionForm.allow_special_characters} onChange={event => updateQuestion('allow_special_characters', event.target.checked)} /> Allow special characters</label></div><Button type="submit">Apply to draft</Button></form></div>}
    {deleteTarget && <div className="modal-backdrop"><section className="question-dialog" role="dialog" aria-modal="true"><h2>Delete {deleteTarget.type}?</h2><p>{deleteTarget.type === 'section' ? 'A section can only be deleted after all its questions are reassigned.' : 'This question will be permanently deleted when you save changes.'} Type <strong>DELETE</strong> to confirm.</p><input autoFocus value={deleteText} onChange={event => setDeleteText(event.target.value)} placeholder="Type DELETE" aria-label="Type DELETE to confirm" /><div className="dialog-actions"><button type="button" onClick={() => setDeleteTarget(null)}>Cancel</button><button type="button" className="danger-button" disabled={deleteText !== 'DELETE'} onClick={confirmDelete}>Delete</button></div></section></div>}
  </main>;
}